1934	                        messageCounter.textContent = `${length} / 1000 characters (${percentage}%)${remaining < 100 && remaining > 0 ? ` - ${remaining} remaining` : ''}`;
1935	                        if (remaining < 100) {
1936	                            messageCounter.style.color = remaining < 50 ? 'var(--error-color)' : 'var(--primary-color)';
1937	                        } else {
1938	                            messageCounter.style.color = 'var(--text-color)';
1939	                        }
1940	                    }
1941	                };
1942	
1943	                if (messageField && messageCounter) {
1944	                    updateMessageCounter();
1945	                    messageField.addEventListener('input', updateMessageCounter);
1946	                }
1947	
1948	                const debouncedValidate = debounce((field) => validateField(field), 300);
1949	
1950	                const inputs = contactForm.querySelectorAll('input, textarea');
1951	                inputs.forEach(input => {
1952	                    input.addEventListener('change', saveFormDraft);
1953	                    input.addEventListener('blur', () => validateField(input));
1954	                    input.addEventListener('input', () => {
1955	                        if (input.getAttribute('aria-invalid') === 'true') {
1956	                            debouncedValidate(input);
1957	                        }
1958	                    });
1959	                });
1960	
1961	                let isSubmitting = false;
1962	
1963	                contactForm.addEventListener('submit', function(e) {
1964	                    e.preventDefault();
1965	
1966	                    if (isSubmitting) return;
1967	
1968	                    let isValid = true;
1969	                    const feedback = document.getElementById('form-feedback');
1970	                    feedback.className = 'form-feedback';
1971	                    feedback.textContent = '';
1972	
1973	                    inputs.forEach(input => {
1974	                        if (!validateField(input)) isValid = false;
1975	                    });
1976	
1977	                    if (!isValid) {
1978	                        feedback.className = 'form-feedback error';
1979	                        feedback.textContent = 'Please correct the errors above and try again.';
1980	                        feedback.setAttribute('role', 'alert');
1981	                        feedback.setAttribute('aria-live', 'assertive');
1982	                        const firstError = contactForm.querySelector('[aria-invalid="true"]');
1983	                        if (firstError && firstError.focus) {
1984	                            firstError.focus();
1985	                        }
1986	                        return;
1987	                    }
1988	
1989	                    const submitBtn = document.getElementById('submit-btn');
1990	                    isSubmitting = true;
1991	                    submitBtn.disabled = true;
1992	                    submitBtn.classList.add('loading');
1993	                    const originalHTML = submitBtn.innerHTML;
1994	                    const originalAriaLabel = submitBtn.getAttribute('aria-label');
1995	                    submitBtn.innerHTML = '<span class="spinner" aria-hidden="true"></span>Sending...';
1996	                    submitBtn.setAttribute('aria-label', 'Sending message, please wait');
1997	                    submitBtn.setAttribute('aria-busy', 'true');
1998	
1999	                    const startTime = Date.now();
2000	                    const minLoadingDuration = 500;
2001	
2002	                    const formData = new FormData(contactForm);
2003	                    const endpoint = contactForm.getAttribute('data-endpoint') || '/contact';
2004	                    const controller = new AbortController();
2005	                    const timeoutId = setTimeout(() => controller.abort(), 10000);
2006	
2007	                    fetch(endpoint, {
2008	                        method: 'POST',
2009	                        body: formData,
2010	                        signal: controller.signal
2011	                    })
2012	                    .then(response => {
2013	                        if (!response.ok) {
2014	                            if (response.status === 429) {
2015	                                throw new Error('Too many requests. Please wait a moment and try again.');
2016	                            } else if (response.status >= 500) {
2017	                                throw new Error('Server is temporarily unavailable. Please try again later.');
2018	                            } else if (response.status >= 400) {
2019	                                throw new Error(`Request error (${response.status}). Please check your input and try again.`);
2020	                            }
2021	                            throw new Error(`Server error: ${response.status}`);
2022	                        }
2023	                        return response;
2024	                    })
2025	                    .then(() => {
2026	                        feedback.className = 'form-feedback success';
2027	                        feedback.textContent = '✓ Thank you for your message! We will be in touch soon.';
2028	                        feedback.setAttribute('role', 'status');
2029	                        feedback.setAttribute('aria-live', 'polite');
2030	                        contactForm.reset();
2031	                        try {
2032	                            localStorage.removeItem(FORM_STORAGE_KEY);
2033	                        } catch (e) {
2034	                            console.debug('Could not clear form draft');
2035	                        }
2036	                        inputs.forEach(input => {
2037	                            clearError(input);
2038	                            input.setAttribute('aria-invalid', 'false');
2039	                        });
2040	                        updateMessageCounter();
2041	                        setTimeout(() => feedback.scrollIntoView({ behavior: 'smooth', block: 'center' }), 100);
2042	                    })
2043	                    .catch(error => {
2044	                        feedback.className = 'form-feedback error';
2045	                        feedback.setAttribute('role', 'alert');
2046	                        feedback.setAttribute('aria-live', 'assertive');
2047	                        if (error.name === 'AbortError') {
2048	                            feedback.textContent = 'Request timed out. Please check your connection and try again.';
2049	                        } else if (error instanceof TypeError) {
2050	                            feedback.textContent = 'Connection failed. Please check your internet connection and try again.';
2051	                        } else if (error.message) {
2052	                            feedback.textContent = error.message;
2053	                        } else {
2054	                            feedback.textContent = 'Something went wrong. Please try again in a moment.';
2055	                            console.error('Form submission error:', error);
2056	                        }
2057	                    })
2058	                    .finally(() => {
2059	                        clearTimeout(timeoutId);
2060	                        const elapsedTime = Date.now() - startTime;
2061	                        const remainingDelay = Math.max(0, minLoadingDuration - elapsedTime);
2062	
2063	                        setTimeout(() => {
2064	                            isSubmitting = false;
2065	                            submitBtn.disabled = false;
2066	                            submitBtn.classList.remove('loading');
2067	                            submitBtn.innerHTML = originalHTML;
2068	                            submitBtn.removeAttribute('aria-busy');
2069	                            if (originalAriaLabel) {
2070	                                submitBtn.setAttribute('aria-label', originalAriaLabel);
2071	                            }
2072	                            requestAnimationFrame(() => {
2073	                                try {
2074	                                    feedback.scrollIntoView({ behavior: 'smooth', block: 'center' });
2075	                                    if (feedback.textContent) {
2076	                                        feedback.setAttribute('tabindex', '-1');
2077	                                        feedback.focus({ preventScroll: true });
2078	                                        feedback.removeAttribute('tabindex');
2079	                                        if (feedback.classList.contains('success')) {
2080	                                            submitBtn.focus();
2081	                                        }
2082	                                    }
2083	                                } catch (e) {
2084	                                    console.error('Error focusing feedback:', e);
2085	                                }
2086	                            });
2087	                        }, remainingDelay);
2088	                    });
2089	                });
2090	            }
2091	        });
2092	    </script>
2093	</body>
